// ========================================
// Cancel Follow-up on Client Reply
// أول Code node في Laila Webhook
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const raw = $input.first().json;

// ── Checkpoint 1: Defensive fromMe detection ──────────
const msgData       = raw.data || raw;
const incomingPhone = msgData?.key?.remoteJid?.replace('@s.whatsapp.net', '');
const isFromBot     = msgData?.key?.fromMe === true || msgData?.message?.fromMe === true;

if (!incomingPhone || isFromBot) {
  console.log(`[CANCEL-FU] skip — phone=${incomingPhone} fromMe=${isFromBot}`);
  return $input.all();
}

console.log(`[CANCEL-FU] client replied → canceling follow-up for ${incomingPhone}`);

// ✅ إلغاء follow-up + تسجيل وقت الرد
const res = await fetch(`${SUPABASE_URL}/rest/v1/leads?phone=eq.${incomingPhone}`, {
  method: 'PATCH',
  headers: {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation',
  },
  body: JSON.stringify({
    next_followup: null,
    last_contact:  new Date().toISOString(),
  }),
});

const data     = await res.json();
const affected = Array.isArray(data) ? data.length : 0;
console.log(`[CANCEL-FU] done — leads updated: ${affected}`);

return $input.all();
